%{
const defaultVehicleNimbleness = Number(entity.system.props.VNIMBLENESS ?? 1);
const fd = await foundry.applications.api.DialogV2.input({
  window: { title: "Driving Skill Test" },
content:
  '<p><strong>Enter the vehicle\'s Nimbleness:</strong></p>' +
  '<input ' +
    'name="vehicleNimbleness" ' +
    'type="number" ' +
    'min="0" ' +
    'max="6" ' +
    'step="1" ' +
    'value="' + defaultVehicleNimbleness + '" ' +
    'autofocus ' +
    'style="width:60px; text-align:center;"' +
  '>',
  ok: {
    label: "FANG IT!"
  }
});

if (!fd) return;

const vehicleNimbleness = Number(fd.vehicleNimbleness ?? 0);
const driverNimbleness = Number(entity.system.props.Nimbleness ?? 0);
const pool = Math.min(driverNimbleness, vehicleNimbleness);

return await game.macros.getName('V6 Roll Engine').execute({
  pool: pool,
  name: 'Driving Skill Test',
  skill: ${Drive}$,
  props: entity.system.props
});
}%

%{
const item = entity;
const actor = item.parent;

const attributeMap = {
  M: "Muscle",
  N: "Nimbleness",
  U: "Understanding"
};

const attributeKey = attributeMap[item.system.props.ATT ?? "M"];
const aimBonus = Number(item.system.props.AIMCNT ?? 0);
const pool = Number(actor?.system?.props?.[attributeKey] ?? 0) + aimBonus;

const skillKey = item.system.props.SKL;
const skill = actor?.system?.props?.[skillKey] ?? 0;

let baseDamage = Number(item.system.props.DMG ?? 0);

if (item.system.props.AddMuscle) {
  baseDamage += Number(actor.system.props.Muscle ?? 0);
}

const currentAmmo = Number(item.system.props.CurAmmo ?? 0);
const capacity = Number(item.system.props.Cap ?? 0);
const usesAmmo = capacity > 0;
const reloadCounter = Number(item.system.props.RLDCNT ?? 0);

if (reloadCounter > 0) {
  ui.notifications.warn(
    `${item.name} is still reloading — ${reloadCounter} reload Action${reloadCounter === 1 ? "" : "s"} remain before it can fire.`
  );
  return;
}
if (usesAmmo && currentAmmo <= 0) {
  ui.notifications.warn("CLICK — OUT OF AMMO");
  return;
}

if (usesAmmo && currentAmmo > 0) {
  await item.update({
    "system.props.CurAmmo": currentAmmo - 1
  });
}

await item.update({
  "system.props.AIMCNT": 0
});

return await game.macros.getName("V6 Roll Engine").execute({
  pool: pool,
  name: item.name,
  skill: skill,
  props: actor.system.props,
  baseDamage: baseDamage,
damageType: item.system.props.Leth ? "L" : "N"
});
}%

%{
const item = entity;

const currentAim = Number(item.system.props.AIMCNT ?? 0);
const newAim = Math.min(currentAim + 1, 2);

await item.update({
  "system.props.AIMCNT": newAim
});

await ChatMessage.create({
  user: game.user.id,
  speaker: ChatMessage.getSpeaker({ actor: item.parent }),
  content: `
    <div class="v6-card">
      <h2>${item.name} — AIM</h2>
      <p>${item.parent.name} spends an Action aiming.</p>
      <p><strong>Aim Bonus:</strong> +${newAim} die${newAim === 1 ? "" : "s"}</p>
    </div>
  `
});
return;
}%

%{
const item = entity;
const actor = item.parent;

const attributeMap = {
  M: "Muscle",
  N: "Nimbleness",
  U: "Understanding"
};

const attributeKey = attributeMap[item.system.props.ATT ?? "M"];
const aimBonus = Number(item.system.props.AIMCNT ?? 0);

const pool =
  Number(actor?.system?.props?.[attributeKey] ?? 0)
  + aimBonus
  + 2;

const skillKey = item.system.props.SKL;
const skill = Number(actor?.system?.props?.[skillKey] ?? 0);

let baseDamage = Number(item.system.props.DMG ?? 0);

if (item.system.props.AddMuscle) {
  baseDamage += Number(actor.system.props.Muscle ?? 0);
}

const currentAmmo = Number(item.system.props.CurAmmo ?? 0);
const burstAmmoCost = item.system.props.ISSHOT ? 1 : 5;

const reloadCounter = Number(item.system.props.RLDCNT ?? 0);

if (reloadCounter > 0) {
  ui.notifications.warn(
    `${item.name} is still reloading — ${reloadCounter} reload Action${reloadCounter === 1 ? "" : "s"} remain before it can fire.`
  );
  return;
}

if (currentAmmo < burstAmmoCost) {
  await ChatMessage.create({
    user: game.user.id,
    speaker: ChatMessage.getSpeaker({ actor }),
    content: `
      <div class="v6-card">
        <h2>NO BULLETS, NO DAKKA!</h2>
        <p>Not enough ammunition for a burst.</p>
      </div>
    `
  });

  return;
}

await item.update({
  "system.props.CurAmmo": currentAmmo - burstAmmoCost,
  "system.props.AIMCNT": 0
});

return await game.macros.getName("V6 Roll Engine").execute({
  pool: pool,
  name: `${item.name} — BURST`,
  skill: skill,
  props: actor.system.props,
  baseDamage: baseDamage,
  damageType: item.system.props.Leth ? "L" : "N"
});
}%

%{
const item = entity;
const actor = item.parent;

const capacity = Number(item.system.props.Cap ?? 0);
const currentAmmo = Number(item.system.props.CurAmmo ?? 0);
const reloadTime = Number(item.system.props.Rld ?? 0);
const reloadCounter = Number(item.system.props.RLDCNT ?? 0);

const newReloadCounter = reloadCounter > 0
  ? reloadCounter - 1
  : Math.max(reloadTime - 1, 0);


const ammoKey = String(item.system.props.ATP ?? "").replace(/^D/, "");
const ammoNameMap = {
  DLHA: "Light Handgun / SMG",
  DMHA: "Medium Handgun / SMG",
  DHHA: "Heavy Handgun / SMG",
  DLRA: "Light Rifle / MG",
  DMRA: "Medium Rifle / MG",
  DHRA: "Heavy Rifle / MG",
  DSHA: "Shotgun",
  DABA: "Arrows"
};

const ammoName = ammoNameMap[item.system.props.ATP] ?? item.system.props.ATP;
const reserveAmmo = Number(actor.system.props[ammoKey] ?? 0);

if (reserveAmmo <= 0) {
  await ChatMessage.create({
    user: game.user.id,
    content: `
      <div class="v6-card">
        <h2>OH SHEET! OUT OF AMMO.</h2>
        <p><strong>${item.name}</strong> has no ${ammoName} ammo available.</p>
      </div>
    `
  });

  return;
}
if (currentAmmo >= capacity) {
  if (reloadCounter > 0) {
    await item.update({
      "system.props.RLDCNT": 0
    });
  }

  ui.notifications.info(`${item.name} is already fully loaded.`);
  return;
}

await item.update({
  "system.props.RLDCNT": newReloadCounter,
  "system.props.AIMCNT": 0
});

await ChatMessage.create({
  user: game.user.id,
  speaker: ChatMessage.getSpeaker({ actor }),
  content: `
    <div class="v6-card">
      <h2>${item.name} — RELOAD</h2>
      ${
        newReloadCounter > 0
          ? `<p>${actor.name} spends an Action reloading.</p>
             <p><strong>${newReloadCounter}</strong> reload Action${newReloadCounter === 1 ? "" : "s"} remain before you can fire this weapon.</p>`
          : `<p>${actor.name} finishes reloading. Weapon will be ready to fire next Action.</p>`
      }
    </div>
  `
});


if (newReloadCounter === 0) {
  const needed = Math.max(0, capacity - currentAmmo);
  const roundsToLoad = Math.min(needed, reserveAmmo);

  await item.update({
    "system.props.CurAmmo": currentAmmo + roundsToLoad,
    "system.props.AIMCNT": 0
  });

  await actor.update({
    [`system.props.${ammoKey}`]: reserveAmmo - roundsToLoad
  });
}
}%

%{
const item = entity;
const actor = item.parent;

const attribute = await foundry.applications.api.DialogV2.wait({
  window: {
    title: `${item.name} — Parry`
  },
  content: `
    <p>Which Attribute are you using to parry?</p>
  `,
  buttons: [
    {
      action: "Muscle",
      label: "Muscle",
      default: true
    },
    {
      action: "Nimbleness",
      label: "Nimbleness"
    }
  ]
});

if (!attribute) return;

const shieldBonus = item.system.props.ISSHIELD ? 1 : 0;
const pool = Number(actor.system.props[attribute] ?? 0) + shieldBonus;
const skill = Number(actor.system.props.Melee ?? 0);

return await game.macros.getName("V6 Roll Engine").execute({
  pool: pool,
  name: `${item.name} Parry`,
  skill: skill,
  props: actor.system.props
});
}%

